w/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Selendra sought Theradras’s defeat so that Zaetar’s remains could be recovered before returning to Stonetalon.",["title"]="Selendra"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7065:description:1-65","7065:description:67-148","7065:description:150-211","7065:description:213-237","7065:description:239-286","7065:description:288-375","7065:description:377-507","7065:objective:1-83"},["minimumStage"]=2,["questID"]=7065,["sourceHash"]="210f2dd2aa3167ca84b6bcc5cd9c28a5b9187584164fcbbea3aae0f60e0b7daf"}},["questSourceProofsMode"]="ANY"},["field"]="motivation",["id"]="catalog-unit-13698",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Keeper Marandis sought help against Theradras as part of recovering Zaetar’s remains and returning to Stonetalon.",["title"]="Keeper Marandis"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7044:description:1-116","7044:description:118-161","7044:description:166-277","7044:description:279-343","7044:description:345-367","7044:description:369-416","7044:description:421-438","7044:description:440-482","7044:description:484-491","7044:objective:1-94","7044:objective:99-132"},["minimumStage"]=2,["questID"]=7044,["sourceHash"]="b5cb68aaf075149b9b0eb8557877f97bf55a3c8da5db7aa28e44b6559d1ff7d4"}},["questSourceProofsMode"]="ANY"},["field"]="conflict",["id"]="atlas-instance-maraudon",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-