_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8288:description:1-26","8288:description:28-48","8288:description:50-223","8288:description:228-290","8288:description:292-390","8288:description:392-442","8288:description:444-499","8288:objective:1-108"},["minimumStage"]=2,["questID"]=8288,["sourceHash"]="28a5add03e25c53fad0d27e38ace6db5b8b56ab6233ce66f4b9f192b29c01797"}},["questSourceProofsMode"]="ANY"},["field"]="location",["id"]="raid-boss-broodlord-lashlayer",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Broodlord Lashlayer guarded the Halls of Strife, blocking passage toward Nefarian’s inner sanctum in Blackwing Lair.",["title"]="Broodlord Lashlayer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8288:description:1-26","8288:description:28-48","8288:description:50-223","8288:description:228-290","8288:description:292-390","8288:description:392-442","8288:description:444-499","8288:objective:1-108"},["minimumStage"]=2,["questID"]=8288,["sourceHash"]="28a5add03e25c53fad0d27e38ace6db5b8b56ab6233ce66f4b9f192b29c01797"}},["questSourceProofsMode"]="ANY"},["field"]="stakes",["id"]="blackwing-lair",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Baristolth made Lashlayer’s head a test for a would-be champion of the Brood, a task requiring an army although only one bearer would advance.",["title"]="Blackwing Lair"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9033:description