ar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4024:description:1-59","4024:description:61-121","4024:description:123-174","4024:description:179-276","4024:description:278-362","4024:description:367-428","4024:description:433-456","4024:objective:1-45","4024:objective:50-110","4024:objective:112-214","4024:objective:219-273"},["minimumStage"]=2,["questID"]=4024,["sourceHash"]="7fc1d9cc9699ac7bfdcd73238055e3b9f63730e6d74aac12a01995919216c097"}},["questSourceProofsMode"]="ANY"},["field"]="motivation",["id"]="catalog-unit-9459",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Cyrus Therepentous coveted the essence of Blackrock's fire. He supplied altered black dragon molt as a vessel for extracting Bael'Gar's inner flame from the giant's remains.",["title"]="Cyrus Therepentous"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4264:description:1-41","4264:description:43-101","4264:description:106-122","4264:description:127-163","4264:description:168-282","4264:description:287-353","4264:description:358-420","4264:description:425-451","4264:objective:1-94","4264:objective:96-124"},["minimumStage"]=2,["questID"]=4264,["sourceHash"]="6c6d444a9ce7cf4164154cc6aff35e08893c7b532cbb8b5cc431d6c9ac5917b9"}},["questSourceProofsMode"]="ANY"},["field"]="relationships",["id"]="catalog-unit-9033",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="A stained note attributed to Emperor Thaurissan credited Angerforge's diligence with uncovering the encryption pattern in Windsor's notes, while Argelmach worked on the decryption.",["title"]="General Angerforge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4132:description:1-35","4132:description:37-84","4132:description:89-198","4132:description:200-263","4132:description:268-372","4132:objective:1-55","4132:objective:57-110"},["minimumStage"]=2,["questID"]=4132,["sourceHash"]="f0ec9d1d83abb74a146868a68f24df1a720a7e08edfb65322037ea9e87595303"}},["questSourceProofsMode"]="ANY"},["field"]="role",["id"]="catalog-unit-9033",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Warlord Goretooth blamed General Angerforge for coordinating attacks on the Kargath Expeditionary Force's 109th division and the slaughter of its soldiers.",["title"]="General Angerforge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4282:description:1-44","4282:description:49-83","4282:description:88-111","4282:description:113-244","4282:description:246-326","4282:description:331-361","4282:description:366-407","4282:description:409-452","4282:objective:1-42","4282:objective:47-153"},["minimumStage"]=2,["questID"]=4282,["sourceHash"]="0646bdd218397b8f280c22bdbe289f74dab7e6353bd9ae3914b97d9322dbbe11"}},["questSourceProofsMode"]="ANY"},["field"]="conflict",["id"]="catalog-unit-8983",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Windsor believed Argelmach and Angerforge held his lost information. Recovering it from the two Dark Iron leaders became a renewed hope after the discovery of the stained note.",["title"]="Golem Lord Argelmach"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4282:description:1-44","4282:description:49-83","4282:description:88-111","4282:description:113-244","4282:description:246-326","4282:description:331-361","4282:description:366-407","4282:description:409-452","4282:objective:1-42","4282:objective:47-153"},["minimumStage"]=2,["questID"]=4282,["sourceHash"]="0646bdd218397b8f280c22bdbe289f74dab7e6353bd9ae3914b97d9322dbbe11"}},["questSourceProofsMode"]="ANY"},["field"]="motivation",["id"]="catalog-unit-9023",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="The discovery of evidence about his lost notes renewed Marshal Windsor's hope. He sent the search toward Angerforge and Argelmach rather than accepting that the information was gone.",["title"]="Marshal Windsor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4132:description:1-35","4132:description:37-84","4132:description:89-198","4132:description:200-263","4132:description:268-372","4132:objective:1-55","4132:objective:57-110"},["minimumStage"]=2,["questID"]=4132,["sourceHash"]="f0ec9d1d83abb74a146868a68f24df1a720a7e08edfb65322037ea9e87595303"}},["questSourceProofsMode"]="ANY"},["field"]="motivation",["id"]="catalog-unit-9077",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Warlord Goretooth's demand for Angerforge's death arose from the attacks on his expeditionary division, presenting the mission as justice for the soldiers killed.",["title"]="Warlord Goretooth"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3802:description:1-79","3802:description:81-123","3802:description:128-259","3802:description:264-341","3802:description:343-400","3802:description:402-505","3802:objective:1-60","3802:objective:62-154"},["minimumStage"]=2,["questID"]=3802,["sourceHash"]="133d9f28941a7c41350aa242e0e1564343f9838f8b48900482fb0538192bf9eb"}},["questSourceProofsMode"]="ANY"},["field"]="relationships",["id"]="catalog-unit-9056",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Fineous Darkvire held Ironfel, the great hammer Franclorn wanted returned to his statue. Restoring it there was meant to reveal the concealed master key.",["title"]="Fineous Darkvire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3802:description:1-79","3802:description:81-123","3802:description:128-259","3802:description:264-341","3802:description:343-400","3802:description:402-505","3802:objective:1-60","3802:objective:62-154"},["minimumStage"]=2,["questID"]=3802,["sourceHash"]="133d9f28941a7c41350aa242e0e1564343f9838f8b48900482fb0538192bf9eb"}},["questSourceProofsMode"]="ANY"},["field"]="context",["id"]="catalog-unit-8888",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Franclorn designed his statue to release a hidden master key when Ironfel was placed in its hands. He warned that any later attempt to remove the hammer would destroy both hammer and statue.",["title"]="Franclorn Forgewright"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2770:description:1-75","2770:description:78-123","2770:description:126-136","2770:description:139-194","2770:description:197-242","2770:description:247-291","2770:description:296-363","2770:description:366-420","2770:objective:1-82"},["minimumStage"]=2,["questID"]=2770,["sourceHash"]="5fa845a44a0b625ae93b1411a604c0d14c281126ac00e0332c7dd87bbccfef94"}},["questSourceProofsMode"]="ANY"},["field"]="appearance",["id"]="atlas-figure-gahzrilla",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Wizzle described Gahz'rilla as a huge beast with energy crackling through its scales, summoned by the sand trolls from a sacred pool within Zul'Farrak.",["title"]="Gahz’rilla"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2770:description:1-75","2770:description:78-123","2770:description:126-136","2770:description:139-194","2770:description:197-242","2770:description:247-291","2770:description:296-363","2770:description:366-420","2770:objective:1-82"},["minimumStage"]=2,["questID"]=2770,["sourceHash"]="5fa845a44a0b625ae93b1411a604c0d14c281126ac00e0332c7dd87bbccfef94"}},["questSourceProofsMode"]="ANY"},["field"]="motivation",["id"]="catalog-unit-4453",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Wizzle Brassbolts wanted to harness the power in Gahz'rilla's electrified scales for his racing car, though he did not know the trolls' secret for summoning the creature.",["title"]="Wizzle Brassbolts"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8947:description:1-111","8947:description:114-165","8947:description:168-240","8947:description:243-287","8947:description:292-362","8947:description:365-438","8947:description:443-480","8947:description:483-508","8947:objective:1-128"},["minimumStage"]=2,["questID"]=8947,["sourceHash"]="cd5426ea512674994c3f0905e4891c4a9364a38c15d6910a391b88c78f69bf21"}},["questSourceProofsMode"]="ANY"},["field"]="history",["id"]="catalog-unit-16059",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Theldren took the first fragment of Valthalak's medallion when the mercenary company's spoils were divided. Anthion reported a brutal failed attempt to retrieve it and later heard that the dwarf had become a Dark Iron gladiator.",["title"]="Theldren"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8948:description:1-61","8948:description:64-116","8948:description:121-216","8948:description:221-296","8948:description:299-327","8948:description:329-347","8948:description:350-396","8948:objective:1-91"},["minimumStage"]=2,["questID"]=8948,["sourceHash"]="f8b0fd29126e5a7827afa411b19e83204d375d42261b3d98a8237f028c01d9c3"}},["questSourceProofsMode"]="ANY"},["field"]="context",["id"]="catalog-unit-16059",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Anthion expected Theldren to avoid a fair challenge. A banner bearing the dwarf's family colors, strengthened with magic and Falrin's procedure, was intended to provoke him into fighting.",["title"]="Theldren"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8947:description:1-111","8947:description:114-165","8947:description:168-240","8947:description:243-287","8947:description:292-362","8947:description:365-438","8947:description:443-480","8947:description:483-508","8947:objective:1-128"},["minimumStage"]=2,["questID"]=8947,["sourceHash"]="cd5426ea512674994c3f0905e4891c4a9364a38c15d6910a391b88c78f69bf21"}},["questSourceProofsMode"]="ANY"},["field"]="history",["id"]="catalog-unit-16016",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Anthion's former mercenary company divided Valthalak's medallion without understanding its importance. His own attempt to reclaim Theldren's fragment left him badly beaten.",["title"]="Anthion Harmon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8948:description:1-61","8948:description:64-116","8948:description:121-216","8948:description:221-296","8948:description:299-327","8948:description:329-347","8948:description:350-396","8948:objective:1-91"},["minimumStage"]=2,["questID"]=8948,["sourceHash"]="f8b0fd29126e5a7827afa411b19e83204d375d42261b3d98a8237f028c01d9c3"}},["questSourceProofsMode"]="ANY"},["field"]="context",["id"]="catalog-unit-16032",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Falrin Treeshaper was the acquaintance Anthion named at Dire Maul's library, credited with knowing how to complete the provocative enchantment on Theldren's family banner.",["title"]="Falrin Treeshaper"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8991:description:1-114","8991:description:116-178","8991:description:180-229","8991:description:234-396","8991:description:401-418","8991:description:420-493","8991:objective:1-77","8991:objective:79-194"},["minimumStage"]=2,["questID"]=8991,["sourceHash"]="dc33b8b7d73ba75abaac275d1e546c431d340d49edffd6b4f24c86d59f0b1699"},{["atomIDs"]={"8968:description:1-114","8968:description:116-177","8968:description:179-228","8968:description:233-395","8968:description:400-417","8968:description:419-492","8968:objective:1-77","8968:objective:79-197"},["minimumStage"]=2,["questID"]=8968,["sourceHash"]="a4ce41066ce77e8c5b0d86faf1df323cc6e141449a12b63d65de61f0494a65b1"}},["questSourceProofsMode"]="ANY"},["field"]="history",["id"]="catalog-unit-16101",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Bodley's report placed Jarien and his sibling Sothos among the former mercenaries who joined the Scarlet Crusade. The account said Dathrohan killed them after failed initiation rites inside his Scarlet Bastion chamber.",["title"]="Jarien"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8991:description:1-114","8991:description:116-178","8991:description:180-229","8991:description:234-396","8991:description:401-418","8991:description:420-493","8991:objective:1-77","8991:objective:79-194"},["minimumStage"]=2,["questID"]=8991,["sourceHash"]="dc33b8b7d73ba75abaac275d1e546c431d340d49edffd6b4f24c86d59f0b1699"},{["atomIDs"]={"8968:description:1-114","8968:description:116-177","8968:description:179-228","8968:description:233-395","8968:description:400-417","8968:description:419-492","8968:objective:1-77","8968:objective:79-197"},["minimumStage"]=2,["questID"]=8968,["sourceHash"]="a4ce41066ce77e8c5b0d86faf1df323cc6e141449a12b63d65de61f0494a65b1"}},["questSourceProofsMode"]="ANY"},["field"]="history",["id"]="catalog-unit-16102",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Sothos and Jarien carried a fragment of Valthalak's amulet after their mercenary company broke up. Bodley reported that their attempt to enter the Scarlet Crusade ended in death during Dathrohan's initiation rites.",["title"]="Sothos"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8991:description:1-114","8991:description:116-178","8991:description:180-229","8991:description:234-396","8991:description:401-418","8991:description:420-493","8991:objective:1-77","8991:objective:79-194"},["minimumStage"]=2,["questID"]=8991,["sourceHash"]="dc33b8b7d73ba75abaac275d1e546c431d340d49edffd6b4f24c86d59f0b1699"},{["atomIDs"]={"8968:description:1-114","8968:description:116-177","8968:description:179-228","8968:description:233-395","8968:description:400-417","8968:description:419-492","8968:objective:1-77","8968:objective:79-197"},["minimumStage"]=2,["questID"]=8968,["sourceHash"]="a4ce41066ce77e8c5b0d86faf1df323cc6e141449a12b63d65de61f0494a65b1"}},["questSourceProofsMode"]="ANY"},["field"]="conflict",["id"]="catalog-unit-10812",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Bodley's information accused Grand Crusader Dathrohan of killing Jarien and Sothos when they failed the Scarlet Crusade's initiation rites in his chamber. This was the reported lead for recovering their medallion fragment.",["title"]="Grand Crusader Dathrohan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1486:description:1-130","1486:description:135-196","1486:description:198-298","1486:description:300-377","1486:description:382-470","1486:objective:1-53"},["minimumStage"]=2,["questID"]=1486,["sourceHash"]="c15c0cc165e4ad66be250671dbfc349b2ffe4375a8c043bdbd81ed514e61519d"}},["questSourceProofsMode"]="ANY"},["field"]="motivation",["id"]="catalog-unit-5767",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Nalpak believed some practical good might come from the Wailing Caverns' corrupted beasts: their unusual hides could be useful in leatherworking despite the nightmare that produced them.",["title"]="Nalpak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1487:description:1-25","1487:description:30-153","1487:description:155-188","1487:description:193-283","1487:description:288-403","1487:description:408-462","1487:objective:1-129"},["minimumStage"]=2,["questID"]=1487,["sourceHash"]="19e6f163ea5b922cc75394ee24400a61e42711e561acefc2b86f31979934d1c5"}},["questSourceProofsMode"]="ANY"},["field"]="motivation",["id"]="catalog-unit-5768",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Ebru shared the concern for Naralex but concentrated on eliminating the deviate creatures while other disciples worked to wake their master from his nightmare.",["title"]="Ebru"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1487:description:1-25","1487:description:30-153","1487:description:155-188","1487:description:193-283","1487:description:288-403","1487:description:408-462","1487:objective:1-129"},["minimumStage"]=2,["questID"]=1487,["sourceHash"]="19e6f163ea5b922cc75394ee24400a61e42711e561acefc2b86f31979934d1c5"}},["questSourceProofsMode"]="ANY"},["field"]="motivation",["id"]="atlas-figure-naralex",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Naralex sought to enter the Emerald Dream and restore the Barrens to lush forest. Ebru's account placed that benevolent aim before the nightmare and corruption that followed.",["title"]="Naralex"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1487:description:1-25","1487:description:30-153","1487:description:155-188","1487:description:193-283","1487:description:288-403","1487:description:408-462","1487:objective:1-129"},["minimumStage"]=2,["questID"]=1487,["sourceHash"]="19e6f163ea5b922cc75394ee24400a61e42711e561acefc2b86f31979934d1c5"}},["questSourceProofsMode"]="ANY"},["field"]="history",["id"]="wailing-caverns",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Naralex's intended restoration of the Barrens became a nightmare, and strange deviate creatures arose within the Wailing Caverns. The remaining disciples divided their efforts between awakening him and fighting the beasts.",["title"]="Wailing Caverns"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2841:description:1-73","2841:description:75-103","2841:description:105-188","2841:description:190-215","2841:description:220-297","2841:description:299-388","2841:description:393-447","2841:description:449-506","2841:objective:1-115"},["minimumStage"]=2,["questID"]=2841,["sourceHash"]="1778273e2204934290a8300f90ace0293bed78fbfe6f8a7a4f2363d33467be67"}},["questSourceProofsMode"]="ANY"},["field"]="relationships",["id"]="gnomeregan",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Nogg's interest in Gnomeregan concerned a new rig design he judged superior to goblin shredders. Its blueprints were locked near Thermaplugg, who alone knew the safe's combination.",["title"]="Gnomeregan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3802:description:1-79","3802:description:81-123","3802:description:128-259","3802:description:264-341","3802:description:343-400","3802:description:402-505","3802:objective:1-60","3802:objective:62-154"},["minimumStage"]=2,["questID"]=3802,["sourceHash"]="133d9f28941a7c41350aa242e0e1564343f9838f8b48900482fb0538192bf9eb"}},["questSourceProofsMode"]="ANY"},["field"]="context",["id"]="quest-place-hall-of-crafting",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={"blackrock-depths"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="The Hall of Crafting lay beyond Blackrock Depths’ Ring of Law; Franclorn’s directions placed Fineous Darkvire there with Ironfel.",["title"]="Hall of Crafting"},{["evidence"]={[