Version"]="boss-quest-context-2026-10-26-r3",["text"]="Ragged John placed Mother Smolderweb in Skitterweb cave within Blackrock Spire, warning of the venom for which she was known.",["title"]="Skitterweb cave"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3528:description:1-62","3528:description:67-154","3528:description:157-200","3528:description:205-241","3528:description:244-370","3528:description:373-442","3528:description:447-505","3528:objective:1-55"},["minimumStage"]=2,["questID"]=3528,["sourceHash"]="60fae1411ca356f80705bbf72d6a4a937532ab7fee3087e91d89180445485c6b"}},["questSourceProofsMode"]="ANY"},["field"]="context",["id"]="quest-place-sanctum-of-the-fallen-god",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={"atlas-instance-the-temple-of-atalhakkar"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="The Sanctum of the Fallen God was the chamber in the Sunken Temple where Yeh’kinya directed the Egg of Hakkar’s ritual, using Hakkari blood to extinguish the binding flames.",["title"]="Sanctum of the Fallen God"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4771:description:1-96","4771:description:99-150","4771:description:155-212","4771:description:214-364","4771:description:369-420","4771:description:423-428","4771:objective:1-59","4771:objective:62-109"},["minimumStage"]=2,["questID"]=4771,["sourceHash"]="2720802a35be93c0835fabb295d9fd59f75831c7529d958829198cc756d151ff"}},["questSourceProofsMode"]="ANY"},["field"]="context",["id"]="quest-place-viewing-room",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={"atlas-instance-scholomance"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014