]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Death Knight Darkreaver held a fallen charger's soul in his service. Grayson directed the trial into Scholomance's Great Ossuary to free the beast from that bondage.",["title"]="Death Knight Darkreaver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7647:description:1-68","7647:description:73-195","7647:description:198-288","7647:description:291-391","7647:description:394-480","7647:description:485-494","7647:objective:1-90","7647:objective:93-145","7647:objective:148-213","7647:objective:216-274","7647:objective:279-376"},["minimumStage"]=2,["questID"]=7647,["sourceHash"]="db046d5646a961ae4c786b068073c8bac5b3270d5cf83e0e4fd929fc177d3513"}},["questSourceProofsMode"]="ANY"},["field"]="context",["id"]="catalog-unit-14516",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Grayson's instructions required judging the accursed spirits drawn by the divination scryer before Darkreaver would appear. His defeat would allow the charger's soul to be recovered.",["title"]="Death Knight Darkreaver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7647:description:1-68","7647:description:73-195","7647:description:198-288","7647:description:291-391","7647:description:394-480","7647:description:485-494","7647:objective:1-90","7647:objective:93-145","7647:objective:148-213","7647:objective:216-274","7647:objective:279-376"},["minimumStage"]=2,["questID"]=7647,["sourceHash"]="db046d5646a961ae4c786b068073c8bac5b3270d5cf83e0e4fd929fc177d3513"}},["questSourceProofsMode"]="ANY"},["field"]="context",["id"]="quest-place-great-ossuary",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={"atlas-instance-scholomance"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Scholomance's Great Ossuary contained skeletal remains including a fallen charger. Grayson directed the divination scryer's use to the heart of its basement, where the trial would draw out Darkreaver.",["title"]="Great Ossuary"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7629:description:1-105","7629:description:108-113","7629:description:115-146","7629:description:149-175","7629:description:180-236","7629:description:239-309","7629:description:314-361","7629:description:364-405","7629:description:408-469","7629:objective:1-61","7629:objective:64-131"},["minimumStage"]=2,["questID"]=7629,["sourceHash"]="2d51d82e416a869d47291d79acc2d42e6686497be161f05efaf8597c07a78690"}},["questSourceProofsMode"]="ANY"},["field"]="context",["id"]="quest-place-alchemy-laboratory-of-scholomance",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={"atlas-instance-scholomance"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Scholomance's alchemy laboratory had equipment Gorzeeki lacked for infusing parchment with Xorothian stardust. He sent a jarred imp to perform the work there.",["title"]="Alchemy Laboratory of Scholomance"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8868:description:1-45","8868:description:48-179","8868:description:182-274","8868:description:279-364","8868:description:367-417","8868:description:422-478","8868:description:481-507","8868:objective:1-50","8868:objective:53-92"},["mi