ion:22-84","8868:completion:87-192","8868:completion:197-352"},["minimumStage"]=4,["questID"]=8868,["sourceHash"]="a0c8822f1860b70c39a85b50c06518052543c629fa947f4f7b85fcd4b5100a7d"}},["questSourceProofsMode"]="ANY"},["field"]="outcome",["id"]="catalog-unit-15467",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Valadar said Elune's blessing prevented Omen from truly dying. Defeat sent his spirit back into the lake and quieted his anger for another year.",["title"]="Omen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4771:description:1-96","4771:description:99-150","4771:description:155-212","4771:description:214-364","4771:description:369-420","4771:description:423-428","4771:objective:1-59","4771:objective:62-109"},["minimumStage"]=2,["questID"]=4771,["sourceHash"]="2720802a35be93c0835fabb295d9fd59f75831c7529d958829198cc756d151ff"}},["questSourceProofsMode"]="ANY"},["field"]="relationships",["id"]="catalog-unit-10432",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Vectus led Scourge scholars in Scholomance's Viewing Room. Betina intended Dawn's Gambit to react with those gathered undead before the mage himself was confronted.",["title"]="Vectus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4771:description:1-96","4771:description:99-150","4771:description:155-212","4771:description:214-364","4771:description:369-420","4771:description:423-428","4771:objective:1-59","4771:objective:62-109","4771:completion:1-11","4771:completion:13-31","4771:completion:33-52","4771:completion:54-65","4771:completion:76-174","4771:completion:176-189","4771:completion:194-259"},["minimumStage"]=4,["questID"]=4771,["sourceHash"]="2720802a35be93c0835fabb295d9fd59f75831c7529d958829198cc756d151ff"}},["questSourceProofsMode"]="ANY"},["field"]="context",["id"]="catalog-unit-10432",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Betina celebrated Vectus's defeat but questioned whether Dawn's Gambit had worked as intended. The outcome did not confirm her hoped-for destruction of the gathered scholars by the device.",["title"]="Vectus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7643:description:1-78","7643:description:81-137","7643:description:140-198","7643:description:201-239","7643:description:244-283","7643:description:286-342","7643:description:345-383","7643:description:386-454","7643:description:456-486","7643:objective:1-59","7643:objective:62-131","7643:objective:136-204","7643:objective:207-251","7643:objective:254-313","7643:objective:316-372"},["minimumStage"]=2,["questID"]=7643,["sourceHash"]="b652d6f4d95c9769bcfed3f90b9aa7d7874d5b9462f4868cb703af257f39873f"}},["questSourceProofsMode"]="ANY"},["field"]="conflict",["id"]="catalog-unit-11489",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Grayson identified Tendris as the corrupt treant holding an Ancient Equine Spirit captive. His judgment called for Tendris's defeat so the spirit could be freed and soothed.",["title"]="Tendris Warpwood"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8962:description:1-19","8962:description:21-231","8962:description:236-369","8962:description:371-499","8962:objective:1-78"},["minimumStage"]=2,["questID"]=8962,["sourceHash"]="4c7c0f727f6783756ef79d5272182647feb264aa6ba000af98067794cd96aa53"}},["questSourceProofsMode"]="ANY"},["field"]="relationships",["id"]="catalog-unit-16080",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Mor Grayhoof had many friends in the Cenarion Circle, including druids killed by silithid around Hive'Regal. Their remains offered Bodley a focus for calling his former comrade's spirit.",["title"]="Mor Grayhoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8963:description:1-19","8963:description:21-231","8963:description:236-305","8963:description:307-485","8963:objective:1-85"},["minimumStage"]=2,["questID"]=8963,["sourceHash"]="8ca11256fdbfb36cf4af9d4a080e063be70d38feb9ef55f5d4e563f2c5b29649"}},["questSourceProofsMode"]="ANY"},["field"]="history",["id"]="catalog-unit-16097",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Isalien grew up at Starbreeze Village in Winterspring. Bodley sought one of its relics among the Frostmaul giants as a link to her life before the amulet's corruption.",["title"]="Isalien"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8964:description:1-19","8964:description:21-233","8964:description:238-319","8964:description:321-377","8964:description:379-488","8964:objective:1-89"},["minimumStage"]=2,["questID"]=8964,["sourceHash"]="eeca6bd46ea4abb400be0c308c6aa19d8bee983ff083866f573f781ae3c5121d"}},["questSourceProofsMode"]="ANY"},["field"]="motivation",["id"]="catalog-unit-16101",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Jarien and Sothos aspired to knighthood within the Scarlet Crusade. Bodley chose a praetorian's sword from Tyr's Hand as a focus tied to their shared ambition.",["title"]="Jarien"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8964:description:1-19","8964:description:21-233","8964:description:238-319","8964:description:321-377","8964:description:379-488","8964:objective:1-89"},["minimumStage"]=2,["questID"]=8964,["sourceHash"]="eeca6bd46ea4abb400be0c308c6aa19d8bee983ff083866f573f781ae3c5121d"}},["questSourceProofsMode"]="ANY"},["field"]="motivation",["id"]="catalog-unit-16102",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Sothos shared Jarien's belief in the Scarlet Crusade and the ambition to become its knights. A sword of zealotry provided the link Bodley needed for their summons.",["title"]="Sothos"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8962:description:1-19","8962:description:21-231","8962:description:236-369","8962:description:371-499","8962:objective:1-78","8962:completion:1-20","8962:completion:22-78","8962:completion:83-305","8962:completion:307-362"},["minimumStage"]=4,["questID"]=8962,["sourceHash"]="4c7c0f727f6783756ef79d5272182647feb264aa6ba000af98067794cd96aa53"}},["questSourceProofsMode"]="ANY"},["field"]="context",["id"]="quest-place-tazz-alaor",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={"atlas-instance-blackrock-spire"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Bodley placed Voone's chamber in Tazz'Alaor in lower Blackrock Spire. The brazier prepared with druidical remains was to call Mor Grayhoof's corrupted spirit there.",["title"]="Tazz'Alaor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8967:description:1-209","8967:description:211-363","8967:description:368-400","8967:description:402-511","8967:objective:1-80","8967:objective:82-200"},["minimumStage"]=2,["questID"]=8967,["sourceHash"]="3d5f6195f66a7f41965903fb95bcaac1ff2cae819db40b21b5fb31a2d94bd821"}},["questSourceProofsMode"]="ANY"},["field"]="context",["id"]="quest-place-shrine-of-eldretharr",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={"dire-maul"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="Bodley reported that Alzzin's forces ambushed Isalien at Dire Maul's Shrine of Eldretharr while she sought the amulet's secrets.",["title"]="Shrine of Eldretharr"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8964:description:1-19","8964:description:21-233","8964:description:238-319","8964:description:321-377","8964:description:379-488","8964:objective:1-89","8964:completion:1-20","8964:completion:22-76","8964:completion:81-265","8964:completion:267-374"},["minimumStage"]=4,["questID"]=8964,["sourceHash"]="eeca6bd46ea4abb400be0c308c6aa19d8bee983ff083866f573f781ae3c5121d"}},["questSourceProofsMode"]="ANY"},["field"]="context",["id"]="quest-place-the-crimson-throne",["qualification"]="SOURCE_ATTRIBUTED_CONTEXT_NOT_PLAYER_ENCOUNTER_OR_OUTCOME_PROOF",["related"]={"atlas-instance-stratholme"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="boss-quest-context-2026-10-26-r3",["text"]="The Crimson Throne lay within Stratholme's Scarlet Bastion. Bodley's sword-bound brazier was to call Jarien and Sothos there, where their souls remained tied to the amulet fragment.",["title"]="The Crimson Throne"}}}
local byID={};for _,e in ipairs(D.entries)do byID[e.id]=e end
local function unique(t,v)for _,x in ipairs(t)do if x==v then return end end;t[#t+1]=v end
for _,e in ipairs(model.newPlaces)do assert(not byID[e.id],'Duplicate named interior');D.entries[#D.entries+1]=e;byID[e.id]=e end
for _,r in ipairs(model.canonicalNPCBindings)do
 local old,new=assert(byID[r.fromID],'Missing indexed NPC'),assert(byID[r.toID],'Missing authored NPC')
 assert(old.catalogReferenceOnly,'Cannot redirect an authored identity')
 local ids={};for _,n in ipairs(old.npcIDs or {})do if n~=r.npcID then ids[#ids+1]=n end end;old.npcIDs=ids
 old.canonicalSubjectID=new.id;old.related=old.related or {};unique(old.related,new.id)
 new.npcIDs=new.npcIDs or {};unique(new.npcIDs,r.npcID)
end
for _,r in ipairs(model.rows)do
 local e=assert(byID[r.id],'Missing boss/cast context target');assert(e.title==r.title)
 local old=e.fields[r.field]
 local basicLabel=e.catalogReferenceMetadata and type(old)=='string' and
  (r.field=='role' and old:find('Reference rank:',1,true)==1 or
   r.field=='location' and (old:find('Location:',1,true)==1 or old:find('Reference location:',1,true)==1) or
   r.field=='context' and (old:find('Type:',1,true)==1 or old:find('Reference level:',1,true)==1 or old:find('Location:',1,true)==1))
 if not old or old=='UNKNOWN' or basicLabel then
  e.fields[r.field]=r.text;e.fieldSources=e.fieldSources or {};e.fieldVersions=e.fieldVersions or {};e.fieldEvidence=e.fieldEvidence or {}
  e.fieldSources[r.field]=r.sourceURL;e.fieldVersions[r.field]=r.sourceVersion;e.fieldEvidence[r.field]=r.evidence
  e.codexEnriched=true;e.catalogReferenceOnly=false
  if e.journalFields then unique(e.journalFields,r.field)end
  e.referenceStatus='PARTIALLY_AUTHORED_SOURCE_CONTEXT_NOT_FULL_BIOGRAPHY'
 end
 e.related=e.related or {};for _,id in ipairs(r.related)do assert(byID[id]);unique(e.related,id)end
end
